php -n -r '
function s($l, $v) { echo str_pad($l, 34), json_encode($v), "\n"; }
s("indexed, all kept", array_filter([1,2,3], fn($v) => true));
s("indexed, first dropped", array_filter([0,1,2], fn($v) => (bool)$v));
s("indexed, middle dropped", array_filter([1,0,3], fn($v) => (bool)$v));
s("indexed, last dropped", array_filter([1,2,0], fn($v) => (bool)$v));
s("indexed, all dropped", array_filter([0,0], fn($v) => (bool)$v));
s("no callback", array_filter([0,1,"",2,null,3]));
s("assoc", array_filter(["a"=>1,"b"=>0,"c"=>2]));
s("USE_KEY", array_filter([1,2,3], fn($k) => $k > 0, ARRAY_FILTER_USE_KEY));
s("USE_BOTH", array_filter([1,2,3], fn($v,$k) => $k > 0 && $v > 1, ARRAY_FILTER_USE_BOTH));
s("string keys mixed", array_filter([0=>"a", "x"=>"", 5=>"b"]));
